// Test-only verifier using pinned ixiosSpark native transaction decoder/Sender.
package main
import("encoding/hex";"fmt";"os";"strconv";"strings";"math/big";"github.com/ixios-io/ixiosSpark/core/types")
func main(){if len(os.Args)!=2&&len(os.Args)!=3{panic("usage: verify raw-hex-file [chain-id: 1 or 3]")};chain:=int64(1);if len(os.Args)==3{c,err:=strconv.ParseInt(os.Args[2],10,64);if err!=nil||(c!=1&&c!=3){panic("chain id must be 1 or 3")};chain=c};data,err:=os.ReadFile(os.Args[1]);if err!=nil{panic(err)};raw,err:=hex.DecodeString(strings.TrimPrefix(strings.TrimSpace(string(data)),"0x"));if err!=nil{panic(err)};var tx types.Transaction;if err=tx.UnmarshalBinary(raw);err!=nil{panic(err)};address,err:=types.Sender(types.NewEIP155Signer(big.NewInt(chain)),&tx);if err!=nil{panic(err)};fmt.Printf("%s %s\n",tx.Hash().Hex(),address.Hex())}
